// c(n.º del gumífono, zona en inglés, contenido en inglés, cómo llegar, opciones).
// Contenido «Map: X» → mapa; `{ juego: true }` → juego del Reino clásico; `{ id }` → id propio.
const zona = (en) => (en ? ZONAS_KH3[en] ?? `«${en}»` : '');
function c(n, zonaEn, cont, t, o = {}) {
  let nombre, tipo, en = cont;
  if (cont.startsWith('Map: ')) { tipo = 'mapa'; nombre = `Mapa: «${cont.slice(5)}»`; }
  else if (o.juego) { tipo = 'juego'; nombre = `«${cont}»`; }
  else { const [es, ti] = OBJ[cont]; tipo = ti; nombre = es ?? `«${cont}»`; }
  return { n, zona: zona(zonaEn), zonaEn, nombre, en, tipo, t, ...o };
}

